      returning id into v_id;
      p_n := p_n + 1;
    else
      v_id := v_ex.id; p_a := p_a + 1;
    end if;
    -- Una partida definitiva queda también aprobada (en el sistema solo una aprobada pasa a definitiva).
    update public.partidas set catalogo_id = v_cat, anio = r.anio, mes = r.mes, numero = r.numero, numero_anual = r.anual,
      fecha = coalesce(r.fecha::timestamp, make_date(r.anio, r.mes, 1)::timestamp)::timestamptz, usuario = upper(r.usuario::text), tipo_partida_id = v_tp,
