      estado = case when upper(r.estado::text) = 'V' then 'VIGENTE' else 'ANULADA' end, clasificacion = r.clasificacion,
      aprobada = upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S', aprobada_por = case when upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S' then upper(r.usuario::text) end,
      aprobada_en = case when upper(r.aprobada::text) = 'S' or upper(r.definitiva::text) = 'S' then r.fecha::timestamp::timestamptz end,
      definitiva = upper(r.definitiva::text) = 'S', definitiva_por = case when upper(r.definitiva::text) = 'S' then upper(r.usuario::text) end,
      definitiva_en = case when upper(r.definitiva::text) = 'S' then r.fecha::timestamp::timestamptz end,
      origen_anterior = 'MIGRADO', estado_anterior = r.estado, modulo_anterior = r.modulo::integer, tipo_anterior = r.tipo, aprobada_anterior = r.aprobada,
      clasificacion_anterior = r.clasif_ant, transaccion_anterior = r.transaccion::integer, transaccion_id = v_tr, moneda_integracion = r.moneda_int::integer,
      valor_cambio_anterior = r.cambio::numeric, anticipo = r.anticipo::boolean, definitiva_anterior = r.definitiva, revisada = r.revisada::boolean
    where id = v_id;
